code.cpp:
class Solution {
public:
    string removeOuterParentheses(string s) {
        string result;
        int balance = 0;
        for (char c : s) {
            if (c == '(') {
                if (balance > 0) result.push_back(c);
                balance++;
            } else {
                balance--;
                if (balance > 0) result.push_back(c);
            }
        }
        return result;
    }
};
